-- SCMS baseline schema. Applied to the dedicated Neon project on 2026-10-18.
-- This migration is for review/version control; run only against a fresh SCMS database.
BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE SCHEMA IF NOT EXISTS scms;
CREATE TYPE scms.app_role AS ENUM ('OWNER_ADMIN','SUPERVISOR','SUBCONTRACTOR');
CREATE TYPE scms.record_status AS ENUM ('DRAFT','SUBMITTED','CHECKED','APPROVED','REJECTED','PARTIALLY_PAID','PAID','REVERSED','CANCELLED');
CREATE TYPE scms.rate_method AS ENUM ('PERCENTAGE','FIXED_REDUCTION','MANUAL_OVERRIDE');
CREATE TYPE scms.payment_method AS ENUM ('CASH','BANK','BKASH','NAGAD','OTHER');
CREATE TABLE scms.app_users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),auth_subject text NOT NULL UNIQUE,full_name text NOT NULL,email text UNIQUE,phone text,role scms.app_role NOT NULL,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE scms.projects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_code text NOT NULL UNIQUE,name text NOT NULL,site_address text,client_name text,start_date date,end_date date,budget numeric(18,2) NOT NULL DEFAULT 0 CHECK(budget>=0),contract_value numeric(18,2) NOT NULL DEFAULT 0 CHECK(contract_value>=0),status text NOT NULL DEFAULT 'PLANNING' CHECK(status IN('PLANNING','ACTIVE','ON_HOLD','COMPLETED','CANCELLED')),notes text,created_by uuid REFERENCES scms.app_users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(end_date IS NULL OR start_date IS NULL OR end_date>=start_date));
CREATE TABLE scms.user_project_assignments(user_id uuid NOT NULL REFERENCES scms.app_users(id),project_id uuid NOT NULL REFERENCES scms.projects(id),assigned_by uuid REFERENCES scms.app_users(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,project_id));
CREATE TABLE scms.main_contracts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL UNIQUE REFERENCES scms.projects(id),client_name text NOT NULL,contract_ref text,contract_value numeric(18,2) NOT NULL DEFAULT 0 CHECK(contract_value>=0),currency char(3) NOT NULL DEFAULT 'BDT',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE scms.main_boq_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES scms.projects(id),item_code text NOT NULL,description text NOT NULL,unit text NOT NULL,main_rate numeric(18,4) NOT NULL CHECK(main_rate>=0),quantity numeric(18,4) NOT NULL DEFAULT 0 CHECK(quantity>=0),revision integer NOT NULL DEFAULT 1 CHECK(revision>0),active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,item_code,revision));
CREATE TABLE scms.subcontractors(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid UNIQUE REFERENCES scms.app_users(id),company_name text,full_name text NOT NULL,phone text,email text,address text,payment_terms text,retention_percent numeric(7,4) NOT NULL DEFAULT 0 CHECK(retention_percent BETWEEN 0 AND 100),status text NOT NULL DEFAULT 'ACTIVE' CHECK(status IN('ACTIVE','INACTIVE','SUSPENDED')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE scms.rate_rules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES scms.projects(id),boq_item_id uuid NOT NULL REFERENCES scms.main_boq_items(id),subcontractor_id uuid NOT NULL REFERENCES scms.subcontractors(id),method scms.rate_method NOT NULL,reduction_percent numeric(7,4) CHECK(reduction_percent BETWEEN 0 AND 100),fixed_reduction numeric(18,4) CHECK(fixed_reduction>=0),manual_rate numeric(18,4) CHECK(manual_rate>=0),approved_rate numeric(18,4) NOT NULL CHECK(approved_rate>=0),revision integer NOT NULL DEFAULT 1,status scms.record_status NOT NULL DEFAULT 'DRAFT',approved_by uuid REFERENCES scms.app_users(id),approved_at timestamptz,created_by uuid REFERENCES scms.app_users(id),created_at timestamptz NOT NULL DEFAULT now(),CHECK(method<>'PERCENTAGE' OR reduction_percent IS NOT NULL),CHECK(method<>'FIXED_REDUCTION' OR fixed_reduction IS NOT NULL),CHECK(method<>'MANUAL_OVERRIDE' OR manual_rate IS NOT NULL));
CREATE TABLE scms.work_orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),work_order_code text NOT NULL UNIQUE,project_id uuid NOT NULL REFERENCES scms.projects(id),subcontractor_id uuid NOT NULL REFERENCES scms.subcontractors(id),status scms.record_status NOT NULL DEFAULT 'DRAFT',start_date date,due_date date,terms text,advance_percent numeric(7,4) NOT NULL DEFAULT 0 CHECK(advance_percent BETWEEN 0 AND 100),retention_percent numeric(7,4) NOT NULL DEFAULT 0 CHECK(retention_percent BETWEEN 0 AND 100),revision integer NOT NULL DEFAULT 1,submitted_at timestamptz,approved_by uuid REFERENCES scms.app_users(id),approved_at timestamptz,created_by uuid REFERENCES scms.app_users(id),created_at timestamptz NOT NULL DEFAULT now(),CHECK(due_date IS NULL OR start_date IS NULL OR due_date>=start_date));
CREATE TABLE scms.work_order_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),work_order_id uuid NOT NULL REFERENCES scms.work_orders(id),boq_item_id uuid REFERENCES scms.main_boq_items(id),item_code_snapshot text NOT NULL,description_snapshot text NOT NULL,unit_snapshot text NOT NULL,assigned_quantity numeric(18,4) NOT NULL CHECK(assigned_quantity>=0),rate_snapshot numeric(18,4) NOT NULL CHECK(rate_snapshot>=0),line_total numeric(18,2) GENERATED ALWAYS AS(round(assigned_quantity*rate_snapshot,2)) STORED);
CREATE TABLE scms.measurements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),measurement_code text NOT NULL UNIQUE,project_id uuid NOT NULL REFERENCES scms.projects(id),work_order_item_id uuid NOT NULL REFERENCES scms.work_order_items(id),measured_on date NOT NULL,method text NOT NULL DEFAULT 'DIRECT' CHECK(method IN('DIRECT','LENGTH_WIDTH_HEIGHT')),length numeric(18,4) CHECK(length>=0),width numeric(18,4) CHECK(width>=0),height numeric(18,4) CHECK(height>=0),direct_quantity numeric(18,4) CHECK(direct_quantity>=0),calculated_quantity numeric(18,4) NOT NULL CHECK(calculated_quantity>=0),location_note text,photo_key text,notes text,status scms.record_status NOT NULL DEFAULT 'SUBMITTED',submitted_by uuid REFERENCES scms.app_users(id),approved_by uuid REFERENCES scms.app_users(id),approved_at timestamptz,rejection_reason text,created_at timestamptz NOT NULL DEFAULT now(),CHECK((method='DIRECT' AND direct_quantity IS NOT NULL) OR(method='LENGTH_WIDTH_HEIGHT' AND length IS NOT NULL AND width IS NOT NULL AND height IS NOT NULL)));
CREATE TABLE scms.subcontractor_bills(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),bill_code text NOT NULL UNIQUE,project_id uuid NOT NULL REFERENCES scms.projects(id),subcontractor_id uuid NOT NULL REFERENCES scms.subcontractors(id),period_start date,period_end date,status scms.record_status NOT NULL DEFAULT 'DRAFT',gross_amount numeric(18,2) NOT NULL DEFAULT 0 CHECK(gross_amount>=0),advance_recovery numeric(18,2) NOT NULL DEFAULT 0 CHECK(advance_recovery>=0),retention_amount numeric(18,2) NOT NULL DEFAULT 0 CHECK(retention_amount>=0),other_deductions numeric(18,2) NOT NULL DEFAULT 0 CHECK(other_deductions>=0),adjustment_amount numeric(18,2) NOT NULL DEFAULT 0,net_payable numeric(18,2) NOT NULL DEFAULT 0,revision integer NOT NULL DEFAULT 1,submitted_at timestamptz,approved_by uuid REFERENCES scms.app_users(id),approved_at timestamptz,created_by uuid REFERENCES scms.app_users(id),created_at timestamptz NOT NULL DEFAULT now(),CHECK(period_end IS NULL OR period_start IS NULL OR period_end>=period_start));
CREATE TABLE scms.subcontractor_bill_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),bill_id uuid NOT NULL REFERENCES scms.subcontractor_bills(id),measurement_id uuid NOT NULL REFERENCES scms.measurements(id),quantity numeric(18,4) NOT NULL CHECK(quantity>0),snapshot_rate numeric(18,4) NOT NULL CHECK(snapshot_rate>=0),line_amount numeric(18,2) GENERATED ALWAYS AS(round(quantity*snapshot_rate,2)) STORED,UNIQUE(measurement_id));
CREATE TABLE scms.advances(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),advance_code text NOT NULL UNIQUE,project_id uuid NOT NULL REFERENCES scms.projects(id),subcontractor_id uuid NOT NULL REFERENCES scms.subcontractors(id),advance_date date NOT NULL,amount numeric(18,2) NOT NULL CHECK(amount>0),purpose text,method scms.payment_method NOT NULL,transaction_ref text,status scms.record_status NOT NULL DEFAULT 'SUBMITTED',approved_by uuid REFERENCES scms.app_users(id),approved_at timestamptz,created_by uuid REFERENCES scms.app_users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE scms.advance_recoveries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),advance_id uuid NOT NULL REFERENCES scms.advances(id),bill_id uuid NOT NULL REFERENCES scms.subcontractor_bills(id),amount numeric(18,2) NOT NULL CHECK(amount>0),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(advance_id,bill_id));
CREATE TABLE scms.payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),payment_code text NOT NULL UNIQUE,project_id uuid REFERENCES scms.projects(id),subcontractor_id uuid REFERENCES scms.subcontractors(id),bill_id uuid REFERENCES scms.subcontractor_bills(id),payee_name text NOT NULL,amount numeric(18,2) NOT NULL CHECK(amount>0),paid_on date NOT NULL,method scms.payment_method NOT NULL,transaction_ref text,receipt_key text,status scms.record_status NOT NULL DEFAULT 'SUBMITTED',approved_by uuid REFERENCES scms.app_users(id),approved_at timestamptz,created_by uuid REFERENCES scms.app_users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(method,transaction_ref));
CREATE TABLE scms.retention_ledger(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES scms.projects(id),subcontractor_id uuid NOT NULL REFERENCES scms.subcontractors(id),bill_id uuid REFERENCES scms.subcontractor_bills(id),entry_type text NOT NULL CHECK(entry_type IN('WITHHOLD','RELEASE','REVERSAL')),amount numeric(18,2) NOT NULL CHECK(amount>0),release_condition text,release_due_date date,approved_by uuid REFERENCES scms.app_users(id),approved_at timestamptz,created_by uuid REFERENCES scms.app_users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE scms.attendance_sheets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES scms.projects(id),work_date date NOT NULL,crew_name text,status scms.record_status NOT NULL DEFAULT 'SUBMITTED',submitted_by uuid REFERENCES scms.app_users(id),approved_by uuid REFERENCES scms.app_users(id),approved_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,work_date,crew_name));
CREATE TABLE scms.attendance_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),sheet_id uuid NOT NULL REFERENCES scms.attendance_sheets(id),worker_code text NOT NULL,worker_name text NOT NULL,trade text,attendance_units numeric(4,2) NOT NULL CHECK(attendance_units IN(0,0.5,1,1.5,2,3)),normal_hours numeric(6,2) NOT NULL DEFAULT 0 CHECK(normal_hours>=0),overtime_hours numeric(6,2) NOT NULL DEFAULT 0 CHECK(overtime_hours>=0),daily_rate numeric(18,2) NOT NULL CHECK(daily_rate>=0),UNIQUE(sheet_id,worker_code));
CREATE TABLE scms.khoraki_claims(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),claim_code text NOT NULL UNIQUE,project_id uuid NOT NULL REFERENCES scms.projects(id),crew_name text NOT NULL,period_start date NOT NULL,period_end date NOT NULL,verified_workers integer NOT NULL CHECK(verified_workers>=0),eligible_days numeric(10,2) NOT NULL CHECK(eligible_days>=0),daily_rate numeric(18,2) NOT NULL CHECK(daily_rate>=0),claim_amount numeric(18,2) GENERATED ALWAYS AS(round(verified_workers*eligible_days*daily_rate,2)) STORED,status scms.record_status NOT NULL DEFAULT 'SUBMITTED',approved_by uuid REFERENCES scms.app_users(id),approved_at timestamptz,created_by uuid REFERENCES scms.app_users(id),created_at timestamptz NOT NULL DEFAULT now(),CHECK(period_end>=period_start),UNIQUE(project_id,crew_name,period_start,period_end));
CREATE TABLE scms.client_bills(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),bill_code text NOT NULL UNIQUE,project_id uuid NOT NULL REFERENCES scms.projects(id),period_start date,period_end date,gross_amount numeric(18,2) NOT NULL DEFAULT 0 CHECK(gross_amount>=0),deductions numeric(18,2) NOT NULL DEFAULT 0 CHECK(deductions>=0),retention_amount numeric(18,2) NOT NULL DEFAULT 0 CHECK(retention_amount>=0),tax_amount numeric(18,2) NOT NULL DEFAULT 0 CHECK(tax_amount>=0),net_amount numeric(18,2) NOT NULL DEFAULT 0,due_date date,status scms.record_status NOT NULL DEFAULT 'DRAFT',created_by uuid REFERENCES scms.app_users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE scms.client_receipts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),receipt_code text NOT NULL UNIQUE,client_bill_id uuid NOT NULL REFERENCES scms.client_bills(id),amount numeric(18,2) NOT NULL CHECK(amount>0),received_on date NOT NULL,method scms.payment_method NOT NULL,transaction_ref text,status scms.record_status NOT NULL DEFAULT 'APPROVED',created_by uuid REFERENCES scms.app_users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(method,transaction_ref));
CREATE TABLE scms.expenses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),expense_code text NOT NULL UNIQUE,project_id uuid REFERENCES scms.projects(id),category text NOT NULL,expense_date date NOT NULL,amount numeric(18,2) NOT NULL CHECK(amount>0),paid_to text,method scms.payment_method NOT NULL,receipt_key text,billable_to_client boolean NOT NULL DEFAULT false,status scms.record_status NOT NULL DEFAULT 'SUBMITTED',notes text,created_by uuid REFERENCES scms.app_users(id),approved_by uuid REFERENCES scms.app_users(id),approved_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE scms.attachments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid REFERENCES scms.projects(id),owner_user_id uuid REFERENCES scms.app_users(id),storage_key text NOT NULL UNIQUE,original_filename text NOT NULL,content_type text,size_bytes bigint CHECK(size_bytes>=0),visibility text NOT NULL DEFAULT 'PRIVATE' CHECK(visibility IN('PRIVATE','PROJECT','SUBCONTRACTOR')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE scms.notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),recipient_user_id uuid NOT NULL REFERENCES scms.app_users(id),event_type text NOT NULL,title text NOT NULL,body text NOT NULL,entity_type text,entity_id uuid,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE scms.audit_logs(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,actor_user_id uuid REFERENCES scms.app_users(id),action text NOT NULL,entity_type text NOT NULL,entity_id text NOT NULL,reason text,old_values jsonb,new_values jsonb,request_id text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE scms.app_settings(setting_key text PRIMARY KEY,setting_value jsonb NOT NULL,updated_by uuid REFERENCES scms.app_users(id),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE scms.backup_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),started_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,status text NOT NULL CHECK(status IN('RUNNING','SUCCESS','FAILED')),backup_location text,error_message text,restore_tested_at timestamptz);
CREATE INDEX idx_projects_status ON scms.projects(status);
CREATE INDEX idx_assignments_project ON scms.user_project_assignments(project_id,user_id);
CREATE INDEX idx_boq_project_item ON scms.main_boq_items(project_id,item_code);
CREATE INDEX idx_work_orders_project_sub ON scms.work_orders(project_id,subcontractor_id,status);
CREATE INDEX idx_measurements_project_date ON scms.measurements(project_id,measured_on,status);
CREATE INDEX idx_bills_sub_status ON scms.subcontractor_bills(subcontractor_id,status,created_at);
CREATE INDEX idx_payments_project_date ON scms.payments(project_id,paid_on,status);
CREATE INDEX idx_expenses_project_date ON scms.expenses(project_id,expense_date,status);
CREATE INDEX idx_notifications_recipient ON scms.notifications(recipient_user_id,read_at,created_at DESC);
CREATE INDEX idx_audit_entity ON scms.audit_logs(entity_type,entity_id,created_at DESC);
ALTER TABLE scms.projects ENABLE ROW LEVEL SECURITY;
ALTER TABLE scms.user_project_assignments ENABLE ROW LEVEL SECURITY;
ALTER TABLE scms.main_contracts ENABLE ROW LEVEL SECURITY;
ALTER TABLE scms.main_boq_items ENABLE ROW LEVEL SECURITY;
ALTER TABLE scms.subcontractors ENABLE ROW LEVEL SECURITY;
ALTER TABLE scms.rate_rules ENABLE ROW LEVEL SECURITY;
ALTER TABLE scms.work_orders ENABLE ROW LEVEL SECURITY;
ALTER TABLE scms.work_order_items ENABLE ROW LEVEL SECURITY;
ALTER TABLE scms.measurements ENABLE ROW LEVEL SECURITY;
ALTER TABLE scms.subcontractor_bills ENABLE ROW LEVEL SECURITY;
ALTER TABLE scms.subcontractor_bill_items ENABLE ROW LEVEL SECURITY;
ALTER TABLE scms.advances ENABLE ROW LEVEL SECURITY;
ALTER TABLE scms.advance_recoveries ENABLE ROW LEVEL SECURITY;
ALTER TABLE scms.payments ENABLE ROW LEVEL SECURITY;
ALTER TABLE scms.retention_ledger ENABLE ROW LEVEL SECURITY;
ALTER TABLE scms.attendance_sheets ENABLE ROW LEVEL SECURITY;
ALTER TABLE scms.attendance_entries ENABLE ROW LEVEL SECURITY;
ALTER TABLE scms.khoraki_claims ENABLE ROW LEVEL SECURITY;
ALTER TABLE scms.client_bills ENABLE ROW LEVEL SECURITY;
ALTER TABLE scms.client_receipts ENABLE ROW LEVEL SECURITY;
ALTER TABLE scms.expenses ENABLE ROW LEVEL SECURITY;
ALTER TABLE scms.attachments ENABLE ROW LEVEL SECURITY;
ALTER TABLE scms.notifications ENABLE ROW LEVEL SECURITY;
ALTER TABLE scms.audit_logs ENABLE ROW LEVEL SECURITY;
-- No client-facing permissive policies yet. Access must go through a trusted authenticated API.
COMMIT;
